// Synthetic URL matrix frozen from the legacy Python 3.11 implementation.
use localbrain_core::backend::references;
use serde_json::Value;
#[test]
fn provider_url_matrix_matches_frozen_legacy_results() {
    let userinfo_url = format!(
        "https://{}:{}@{}/browse/PAY-1",
        "account", "value", "jira.example.test"
    );
    let cases: Vec<Value> =
        serde_json::from_str(&CASES.replace("__SYNTHETIC_USERINFO_URL__", &userinfo_url)).unwrap();
    for case in cases {
        let url = case["url"].as_str().unwrap();
        let locator = references::describe_atlassian_url(url);
        assert_eq!(
            serde_json::to_value(&locator).unwrap(),
            case["locator"],
            "locator: {url:?}"
        );
        assert_eq!(
            serde_json::to_value(references::atlassian_locator_identity(&locator)).unwrap(),
            case["identity"],
            "identity: {url:?}"
        );
        assert_eq!(
            serde_json::to_value(references::parse_url(url)).unwrap(),
            case["parsed"],
            "parsed: {url:?}"
        );
        assert_eq!(
            serde_json::to_value(references::safe_generic_url(url)).unwrap(),
            case["generic"],
            "generic: {url:?}"
        );
    }
}
